package com.wizzadrds.theworldremembers.knowledge; import com.mojang.serialization.Codec; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class ConversationManager extends SavedData{private static final int MAX=2048;private final List<ConversationRecord> records=new ArrayList<>();private static final Codec<ConversationManager>C=ConversationRecord.CODEC.listOf().xmap(list->{var x=new ConversationManager();x.records.addAll(list);return x;},x->x.records);private static final SavedDataType<ConversationManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","conversations"),ConversationManager::new,C,null);public static ConversationManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new ConversationManager():l.getDataStorage().computeIfAbsent(TYPE);}public boolean talk(UUID speaker,UUID listener,String eventId,long tick,KnowledgeManager knowledge){var source=knowledge.factsOf(speaker).stream().filter(f->f.eventId().equals(eventId)).findFirst();if(source.isEmpty())return false;if(records.stream().anyMatch(r->r.speaker().equals(speaker)&&r.listener().equals(listener)&&r.eventId().equals(eventId)))return false;boolean transferred=knowledge.report(listener,speaker,source.get(),tick);records.add(new ConversationRecord(speaker,listener,eventId,tick,transferred));while(records.size()>MAX)records.remove(0);setDirty();return transferred;}public List<ConversationRecord> all(){return List.copyOf(records);}}